do_if.value:
$candStation.dockingallowed.{$candRanger} and @$candStation.dock.{$candDockSize}.isdockingallowed
                  and @$candStation.dock.{$candDockSize}.todockpos != null
                  and not $candStation.isblacklisted.{blacklisttype.objectactivity}.{$candGroup}.{$candRanger}
                  and not $candStation.sector.isblacklisted.{blacklisttype.sectoractivity}.{$candGroup}.{$candRanger}
                  and not $candStation.sector.isblacklisted.{blacklisttype.sectortravel}.{$candGroup}.{$candRanger}
